    @Throws(BaluardException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `addCipher`(`payload`: kotlin.String) : kotlin.String {
        return uniffiRustCallAsync(
