/**
 * @suppress
 */
public object FfiConverterTypeMobileVault: FfiConverter<MobileVault, Pointer> {

    override fun lower(value: MobileVault): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): MobileVault {
        return MobileVault(value)
    }

    override fun read(buf: ByteBuffer): MobileVault {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: MobileVault) = 8UL

    override fun write(value: MobileVault, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



